    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background-color: #4f545c;
    color: #ffffff;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background-color: #36393f;
}

.thread-root-message .message-content {
    font-size: 0.85rem;
    color: #b9bbbe;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.thread-reply {
    padding: 6px 0;
}

